+      'Exact Match': { exact_match: null },
+    },
+    extractedColumns: { answer: 'London', answer2: 'London' },
+  },
+  {
+    id: 'r2',
+    executionStatus: ExtractionResultStatus.SUCCESS,
+    testCaseName: 'Round 2',
+    runIndex: 1,
+    requestIndex: 1,
+    totalRequests: 2,
+    turnIndex: 0,
+    totalTurns: 2,
+    responseStatusCode: 200,
+    executionInfo: { durationMs: 796 },
+    metricValues: {
+      'DeepEval: Answer Relevancy': { score: 1 },
+      'Exact Match': { exact_match: null },
+    },
+    extractedColumns: { answer: 'Hello! How can I help you today?' },
+  },
+] as unknown as AnalyticsResult[];
+
+const LEAF_HEADERS = {
+  numeric: ['# Run number', 'Request', 'Total requests', 'Turn', 'Total turns', 'HTTP', 'Duration'],
+  metric: ['score', 'exact_match'],
+  text: ['Test Case name', 'answer', 'answer2'],
+};
+const GROUP_HEADERS = ['Execution', 'DeepEval: Answer Relevancy', 'Exact Match', 'Extracted'];
+
+// Every column is switched on, as an operator can do from the Columns panel, so that every header renders.
+const showEveryColumn = (columns: (ColDef | ColGroupDef)[]): (ColDef | ColGroupDef)[] =>
+  columns.map((column) =>
+    'children' in column && Array.isArray(column.children)
+      ? { ...column, children: showEveryColumn(column.children) }
+      : { ...column, hide: false },
+  );
+
+const Harness: FC = () => {
+  const [state, setState] = useState<ExtractionResultTabUiState>(() => {
+    const colDefs = showEveryColumn(getAnalyticsColumns(RESULTS)) as ColDef[];
+    return {
+      ...createDefaultRunViewTabState().extractionResult,
+      results: RESULTS,
+      colDefs,
+      panelColDefs: colDefs,
+    };
+  });
+  const patchState = useCallback((patch: Partial<ExtractionResultTabUiState>) => {
+    setState((prev) => ({ ...prev, ...patch }));
+  }, []);
+
+  return (
+    <div style={{ width: 4000, height: 800 }}>
+      <ExtractionResultTab
+        run={{ id: 'run-1' } as never}
+        extractionResultState={state}
+        setExtractionResultState={patchState}
+      />
+    </div>
+  );
+};
+
+// ---- reading a rendered header ----------------------------------------------------------------------
+const ownText = (element: Element) => element.textContent?.replace(/\s+/g, ' ').trim();
+
+/** The innermost element of the header cell whose whole text is the label. */
+const findLabel = (cell: Element, text: string): HTMLElement | undefined =>
+  Array.from(cell.querySelectorAll<HTMLElement>('*')).find(
+    (element) => ownText(element) === text && !Array.from(element.children).some((child) => ownText(child) === text),
+  );
+
+const findHeader = async (selector: string, text: string) =>
+  waitFor(() => {
+    const cell = Array.from(document.querySelectorAll(selector)).find((candidate) => ownText(candidate) === text);
+    const label = cell && findLabel(cell, text);
+    if (!cell || !label) throw new Error(`header "${text}" is not rendered`);
+    return { cell, label };
+  });
+
+// Every check below reads the look the label ends up with under the app's real stylesheet (see header-look).
+const expectSmallSemiboldSentenceCase = (styles: PageStyles, label: Element, text: string) => {
+  const look = headerLook(styles, label);
+  expect(isSmallSemibold(look), `"${text}" is small semibold text, got ${JSON.stringify(look)}`).toBe(true);
+  expect(isSentenceCase(look), `"${text}" keeps its own letter case and spacing, got ${JSON.stringify(look)}`).toBe(
+    true,
+  );
+};
+
+const expectSmallSemiboldGroupLabel = (styles: PageStyles, label: Element, text: string) => {
+  // The grid's own group label already has the design's look; a custom group label must match it.
+  if (label.closest('.ag-header-group-text')) return;
+  const look = headerLook(styles, label);
+  expect(isSmallSemibold(look), `"${text}" is small semibold text, got ${JSON.stringify(look)}`).toBe(true);
+};
+
+describe('Extraction result grid header row', () => {
+  let widthStubs: { mockRestore: () => void }[] = [];
+  let styles: PageStyles;
+
+  beforeAll(async () => {
+    styles = await loadPageStyles();
+  }, 120_000);
+
+  beforeEach(() => {
+    // jsdom lays nothing out, so the grid would see a zero-wide viewport and skip the columns past it.
+    widthStubs = (['clientWidth', 'offsetWidth'] as const).map((property) =>
+      vi.spyOn(HTMLElement.prototype, property, 'get').mockReturnValue(4000),
+    );
+  });
+
+  afterEach(() => {
+    widthStubs.forEach((stub) => stub.mockRestore());
+  });
+
+  test('every column header reads as small semibold sentence-case text', async () => {
+    render(<Harness />);
+
+    for (const text of [...LEAF_HEADERS.text, ...LEAF_HEADERS.numeric, ...LEAF_HEADERS.metric]) {
+      const { label } = await findHeader('.ag-header-cell', text);
+      expectSmallSemiboldSentenceCase(styles, label, text);
+    }
+  });
+
+  test('numeric column headers line up with their right-aligned values', async () => {
+    render(<Harness />);
+
+    for (const text of [...LEAF_HEADERS.numeric, ...LEAF_HEADERS.metric]) {
+      const { cell, label } = await findHeader('.ag-header-cell', text);
+      expect(isRightAligned(styles, cell, label), `"${text}" header is right-aligned`).toBe(true);
+    }
+  });
+
+  test('text column headers stay left-aligned', async () => {
+    render(<Harness />);
+
+    for (const text of LEAF_HEADERS.text) {
+      const { cell, label } = await findHeader('.ag-header-cell', text);
+      expect(isRightAligned(styles, cell, label), `"${text}" header is left-aligned`).toBe(false);
+    }
+  });
+
+  test('column group labels read as small semibold text', async () => {
+    render(<Harness />);
+
+    for (const text of GROUP_HEADERS) {
+      const { label } = await findHeader('.ag-header-group-cell', text);
+      expectSmallSemiboldGroupLabel(styles, label, text);
+    }
+  });
+});
